def boxes(g):
    # connected components (color-distinguishing) using simple scan; treat any nonzero as object
    seen=[[False]*len(r) for r in g]; out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]!=0 and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<len(g) and 0<=nb<len(g[0]) and g[na][nb]!=0 and not seen[na][nb]:
                            seen[na][nb]=True; st.append((na,nb))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                out.append((g[i][j],min(rs),max(rs),min(cs),max(cs)))
    return out

def solve(g):
    comps=boxes(g)
    out=[]
    for col,r0,r1,c0,c1 in comps:
        out.append([[0]*(c1-c0+1)]*3)
        for dr,dc in zip(range(r1-r0+1),range(c1-c0+1)):
            out[-1][dr][dc]=col
    return [list(map(sum,zip(*out)))]

